def login_required(view):
    @wraps(view)
    def wrapper(*args, **kwargs):
        if "user_id" not in session:
            return redirect(url_for("login"))
        return view(*args, **kwargs)
    return wrapper

def admin_only(view):
    @wraps(view)
    def wrapper(*args, **kwargs):
        if session.get("user_id") != 1:
            abort(403)
        return view(*args, **kwargs)
    return wrapper
